# Homebrew formula for the Sweepsafe CLI beta: installs the prebuilt binary from the npm registry
# tarballs (the same bytes published as @adventures92/sweepsafe-darwin-{arm64,x64}).
# Generated by dist/homebrew/render-npm.sh from dist/homebrew/sweepsafe-npm.rb.tmpl; publish the
# rendered file as sweepsafe.rb (or Formula/sweepsafe.rb) in adventures92/homebrew-tap.
class Sweepsafe < Formula
  desc "Explainable Mac disk cleanup: your agent looks, you decide, code moves it"
  homepage "https://sweepsafe.adventures92.com"
  # The formula's own source is the tiny npm launcher package (never run); the native binary comes
  # from the per-architecture npm package, declared as a resource because Homebrew does not allow
  # `url` inside on_arm/on_intel.
  url "https://registry.npmjs.org/sweepsafe/-/sweepsafe-0.1.0-beta.1.tgz"
  sha256 "7c277e23b5c3bc6eaafd643f259229cad22cae528e407ba311c49519373e4ba3"
  license "MIT"

  depends_on :macos

  resource "binary" do
    on_arm do
      url "https://registry.npmjs.org/@adventures92/sweepsafe-darwin-arm64/-/sweepsafe-darwin-arm64-0.1.0-beta.1.tgz"
      sha256 "2f05ae1aff387832cfbb0f445bc7608ad9959d6a7f42d386ec05d9214d340bdb"
    end

    on_intel do
      url "https://registry.npmjs.org/@adventures92/sweepsafe-darwin-x64/-/sweepsafe-darwin-x64-0.1.0-beta.1.tgz"
      sha256 "5ba2b9478892b7d575fb7125beed6837f1a5a29f94f8e0b96c96acd8d0482cbb"
    end
  end

  def install
    resource("binary").stage { bin.install "bin/sweepsafe" }
    # The npm tarball carries only the binary; man pages and completions come from the binary itself.
    system bin/"sweepsafe", "man", "--out-dir", man1
    generate_completions_from_executable(bin/"sweepsafe", "completions")
  end

  def caveats
    <<~EOS
      Sweepsafe needs Full Disk Access for your terminal to measure ~/Library:
        sweepsafe doctor
      Real moves stay off until you list the folders it may act in:
        ~/Library/Application Support/Sweepsafe/executor.json  {"allowedRoots": ["#{Dir.home}"]}
    EOS
  end

  test do
    assert_match "sweepsafe #{version}", shell_output("#{bin}/sweepsafe --version")
    assert_match "#compdef sweepsafe", shell_output("#{bin}/sweepsafe completions zsh")
    # CHECK FIRST is never bulk-selected, even from a script.
    (testpath/"scan.json").write <<~JSON
      {"scanId":"t","startedAt":"2026-01-01T00:00:00Z","home":"#{testpath}","roots":[],
       "scan":{"files":0,"seconds":0,"unclearFolders":0,"tokens":0,"lanes":[],"steps":[],"log":[]},
       "findings":[]}
    JSON
    output = shell_output(
      "#{bin}/sweepsafe --home #{testpath} plan #{testpath}/scan.json --tiers check_first 2>&1", 1
    )
    assert_match "never bulk-selected", output
  end
end
